CREATE TABLE registrations (id BIGINT PRIMARY KEY AUTO_INCREMENT, registration_number VARCHAR(40) NOT NULL, event_id BIGINT NOT NULL, user_id BIGINT NOT NULL, registered_at TIMESTAMP NOT NULL, status VARCHAR(20) NOT NULL, CONSTRAINT uk_registration_number UNIQUE(registration_number), CONSTRAINT uk_registration_event_user UNIQUE(event_id,user_id), CONSTRAINT fk_reg_event FOREIGN KEY(event_id) REFERENCES events(id), CONSTRAINT fk_reg_user FOREIGN KEY(user_id) REFERENCES users(id), INDEX idx_reg_event_status(event_id,status), INDEX idx_reg_user(user_id));
CREATE TABLE waitlist_entries (id BIGINT PRIMARY KEY AUTO_INCREMENT,event_id BIGINT NOT NULL,user_id BIGINT NOT NULL,position INT NOT NULL,status VARCHAR(20) NOT NULL,joined_at TIMESTAMP NOT NULL,CONSTRAINT uk_waitlist_event_user UNIQUE(event_id,user_id),CONSTRAINT fk_wait_event FOREIGN KEY(event_id) REFERENCES events(id),CONSTRAINT fk_wait_user FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_wait_event_position(event_id,position));
CREATE TABLE tickets (id BIGINT PRIMARY KEY AUTO_INCREMENT,ticket_id VARCHAR(50) NOT NULL,registration_id BIGINT NOT NULL,secure_token_hash CHAR(64) NOT NULL,issued_at TIMESTAMP NOT NULL,CONSTRAINT uk_ticket_id UNIQUE(ticket_id),CONSTRAINT uk_ticket_registration UNIQUE(registration_id),CONSTRAINT fk_ticket_registration FOREIGN KEY(registration_id) REFERENCES registrations(id),INDEX idx_ticket_token_hash(secure_token_hash));
CREATE TABLE attendance (id BIGINT PRIMARY KEY AUTO_INCREMENT,registration_id BIGINT NOT NULL,event_id BIGINT NOT NULL,checked_in_by BIGINT NOT NULL,checked_in_at TIMESTAMP NOT NULL,status VARCHAR(20) NOT NULL,CONSTRAINT uk_attendance_registration UNIQUE(registration_id),CONSTRAINT fk_att_reg FOREIGN KEY(registration_id) REFERENCES registrations(id),CONSTRAINT fk_att_event FOREIGN KEY(event_id) REFERENCES events(id),CONSTRAINT fk_att_user FOREIGN KEY(checked_in_by) REFERENCES users(id),INDEX idx_attendance_event(event_id));
